    public void testToString_with_null_reader() throws IOException {
        cr = new CharacterReader(null);
        Assert.assertEquals("", cr.toString());
    }

    @Test
    public void testToString_with_empty_reader() throws IOException {
        cr = new CharacterReader(new StringReader(""));
        Assert.assertEquals("", cr.toString());
    }

    @Test
    public void testToString_with_binary_reader() throws IOException {
